import {validRun,achievements,leaderboardSort,weekStart} from './engine.js';
const KEY='lions-gate-arcade-v3';
export const cleanNickname=value=>String(value||'PLAYER 1').replace(/[^a-zA-Z0-9 _-]/g,'').trim().slice(0,16)||'PLAYER 1';
export function emptyProfile(){return {version:3,nickname:'PLAYER 1',run:null,records:[],badges:[],bestScore:0,bestCompleted:0,settings:{sound:false,music:false,shortJourneys:false}}}
export function loadProfile(storage,bank){try{const p=JSON.parse(storage.getItem(KEY));if(!p||p.version!==3)return emptyProfile();const base=emptyProfile();return {...base,nickname:cleanNickname(p.nickname),run:validRun(p.run,bank)?p.run:null,records:Array.isArray(p.records)?p.records.filter(r=>typeof r.id==='string'&&Number.isSafeInteger(r.score)&&r.score>=0&&Number.isInteger(r.completed)&&r.completed>=0&&Number.isFinite(Date.parse(r.endedAt))).slice(0,100):[],badges:Array.isArray(p.badges)?p.badges.filter(b=>typeof b==='string').slice(0,30):[],bestScore:Number.isSafeInteger(p.bestScore)?Math.max(0,p.bestScore):0,bestCompleted:Number.isSafeInteger(p.bestCompleted)?Math.max(0,p.bestCompleted):0,settings:{sound:p.settings?.sound===true,music:p.settings?.music===true,shortJourneys:p.settings?.shortJourneys===true}}}catch{return emptyProfile()}}
export function saveProfile(storage,p){try{storage.setItem(KEY,JSON.stringify(p));return true}catch{return false}}
export function captureProgress(profile,run){profile.run=run;profile.bestScore=Math.max(profile.bestScore,run.score);profile.bestCompleted=Math.max(profile.bestCompleted,run.completed);profile.badges=[...new Set([...profile.badges,...achievements(run)])];
 if(run.status==='gameover'){const row={id:run.id,nickname:cleanNickname(run.nickname),score:run.score,completed:run.completed,level:run.level,endedAt:run.endedAt};profile.records=[...profile.records.filter(r=>r.id!==row.id),row].sort(leaderboardSort).slice(0,100)}else profile.records=profile.records.filter(r=>r.id!==run.id);return profile;
}
export function localScores(profile,filter='all',now=new Date()){return profile.records.filter(r=>filter!=='week'||r.endedAt>=weekStart(now)).sort(leaderboardSort)}
